From a2639a7f0f5bf7d73f337f8f077c19415c62ed2c Mon Sep 17 00:00:00 2001
From: Pauli Virtanen <pav@iki.fi>
Date: Sun, 29 Mar 2026 16:43:01 +0300
Subject: [PATCH] Bluetooth: hci_conn: fix potential UAF in set_cig_params_sync

hci_conn lookup and field access must be covered by hdev lock in
set_cig_params_sync, otherwise it's possible it is freed concurrently.

Take hdev lock to prevent hci_conn from being deleted or modified
concurrently.  Just RCU lock is not suitable here, as we also want to
avoid "tearing" in the configuration.

Fixes: a091289218202 ("Bluetooth: hci_conn: Fix hci_le_set_cig_params")
Signed-off-by: Pauli Virtanen <pav@iki.fi>
Signed-off-by: Luiz Augusto von Dentz <luiz.von.dentz@intel.com>

diff --git a/net/bluetooth/hci_conn.c b/net/bluetooth/hci_conn.c
index e6393f17576b..11d3ad8d2551 100644
--- a/net/bluetooth/hci_conn.c
+++ b/net/bluetooth/hci_conn.c
@@ -1843,9 +1843,13 @@ static int set_cig_params_sync(struct hci_dev *hdev, void *data)
 	u8 aux_num_cis = 0;
 	u8 cis_id;

+	hci_dev_lock(hdev);
+
 	conn = hci_conn_hash_lookup_cig(hdev, cig_id);
-	if (!conn)
+	if (!conn) {
+		hci_dev_unlock(hdev);
 		return 0;
+	}

 	qos = &conn->iso_qos;
 	pdu->cig_id = cig_id;
@@ -1884,6 +1888,8 @@ static int set_cig_params_sync(struct hci_dev *hdev, void *data)
 	}
 	pdu->num_cis = aux_num_cis;

+	hci_dev_unlock(hdev);
+
 	if (!pdu->num_cis)
 		return 0;

-- 
2.34.1

Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
Bluetooth: hci_conn: fix potential UAF in set_cig_params_sync

hci_conn lookup and field access must be covered by hdev lock in
set_cig_params_sync, otherwise it's possible it is freed concurrently.

Take hdev lock to prevent hci_conn from being deleted or modified
concurrently.  Just RCU lock is not suitable here, as we also want to
avoid "tearing" in the configuration.

Fixes: a091289218202 ("Bluetooth: hci_conn: Fix hci_le_set_cig_params")
Signed-off-by: Pauli Virtanen <pav@iki.fi>
Signed-off-by: Luiz Augusto von Dentz <luiz.von.dentz@intel.com>

Here is the root cause:
set_cig_params_sync accesses hci_conn without holding the hdev lock, allowing concurrent deletion or modification of the connection, leading to a use-after-free.

Here is the patch:

 static int set_cig_params_sync(struct hci_dev *hdev, void *data)
 {
 	DEFINE_FLEX(struct hci_cp_le_set_cig_params, pdu, cis, num_cis, 0x1f);
 	u8 cig_id = PTR_UINT(data);
 	struct hci_conn *conn;
 	struct bt_iso_qos *qos;
 	u8 aux_num_cis = 0;
 	u8 cis_id;

+	hci_dev_lock(hdev);
+
 	conn = hci_conn_hash_lookup_cig(hdev, cig_id);
-	if (!conn)
+	if (!conn) {
+		hci_dev_unlock(hdev);
 		return 0;
+	}

 	qos = &conn->iso_qos;
 	pdu->cig_id = cig_id;
 	hci_cpu_to_le24(qos->ucast.out.interval, pdu->c_interval);
 	hci_cpu_to_le24(qos->ucast.in.interval, pdu->p_interval);
 	pdu->sca = qos->ucast.sca;
 	pdu->packing = qos->ucast.packing;
 	pdu->framing = qos->ucast.framing;
 	pdu->c_latency = cpu_to_le16(qos->ucast.out.latency);
 	pdu->p_latency = cpu_to_le16(qos->ucast.in.latency);

 	/* Reprogram all CIS(s) with the same CIG, valid range are:
 	 * num_cis: 0x00 to 0x1F
 	 * cis_id: 0x00 to 0xEF
 	 */
 	for (cis_id = 0x00; cis_id < 0xf0 &&
 	     aux_num_cis < pdu->num_cis; cis_id++) {
 		struct hci_cis_params *cis;

 		conn = hci_conn_hash_lookup_cis(hdev, NULL, 0, cig_id, cis_id);
 		if (!conn)
 			continue;

 		qos = &conn->iso_qos;

 		cis = &pdu->cis[aux_num_cis++];
 		cis->cis_id = cis_id;
 		cis->c_sdu  = cpu_to_le16(conn->iso_qos.ucast.out.sdu);
 		cis->p_sdu  = cpu_to_le16(conn->iso_qos.ucast.in.sdu);
 		cis->c_phys = qos->ucast.out.phys ? qos->ucast.out.phys :
 			      qos->ucast.in.phys;
 		cis->p_phys = qos->ucast.in.phys ? qos->ucast.in.phys :
 			      qos->ucast.out.phys;
 		cis->c_rtn  = qos->ucast.out.rtn;
 		cis->p_rtn  = qos->ucast.in.rtn;
 	}
 	pdu->num_cis = aux_num_cis;

+	hci_dev_unlock(hdev);
+
 	if (!pdu->num_cis)
 		return 0;

 	return __hci_cmd_sync_status(hdev, HCI_OP_LE_SET_CIG_PARAMS,
 				     struct_size(pdu, cis, pdu->num_cis),
 				     pdu, HCI_CMD_TIMEOUT);
 }



